/**
 * Core types for the CodeKids block-programming engine.
 *
 * A child's program is a tree of blocks (AST). The same interpreter runs on the
 * client (to animate the board) and on the server (to validate the solution and
 * compute stars), so the client can never "fake" a success.
 */

export type Concept = "sequencing" | "looping" | "conditional";
export type Subject = "IPA" | "Matematika";

export type ActionBlock = { id: string; kind: "action"; action: string };
export type RepeatBlock = { id: string; kind: "repeat"; times: number; body: Block[] };
export type IfBlock = {
  id: string;
  kind: "if";
  cond: string;
  then: Block[];
  else: Block[];
};
export type Block = ActionBlock | RepeatBlock | IfBlock;
export type Program = Block[];

export const ENGINE_LIMITS = {
  maxRepeat: 10,
  minRepeat: 2,
  maxDepth: 3,
  maxBlocks: 30,
  maxSteps: 400,
} as const;

/* ----------------------------- World definitions ---------------------------- */

export type Direction = "N" | "E" | "S" | "W";

/**
 * Grid cell legend:
 *  '.' empty   '#' wall      'G' goal       'I' collectible item
 *  'P' pot (needs water)     'S' seedling (needs water)
 *  'R' ripe fruit (pick)     'O' rock (jump over)
 */
export type GridWorld = {
  type: "grid";
  width: number;
  height: number;
  start: { x: number; y: number; dir: Direction };
  hero: string;
  /** One or more layouts. The program must succeed on every layout. */
  layouts: string[][];
  legend?: Partial<Record<"G" | "I" | "P" | "S" | "R" | "O" | "#", string>>;
  goal: { reach?: boolean; collectAll?: boolean; waterAll?: boolean; pickAll?: boolean };
};

export type NumberLineWorld = {
  type: "numberline";
  start: number;
  target: number;
  min: number;
  max: number;
  hero: string;
  /** Optional marks to show on the line (e.g. pattern 5, 10, 15). */
  marks?: number[];
};

export type SortItem = {
  label: string;
  emoji?: string;
  props: Record<string, boolean>;
  answer: string;
};

export type SortWorld = {
  type: "sort";
  items: SortItem[];
  bins: { id: string; label: string; emoji: string }[];
};

export type SequenceWorld = {
  type: "sequence";
  cards: { id: string; label: string; emoji: string }[];
  answer: string[];
};

export type World = GridWorld | NumberLineWorld | SortWorld | SequenceWorld;

/* -------------------------------- Mission ---------------------------------- */

export type PaletteAction = { action: string; label: string; icon: string };
export type PaletteCondition = { id: string; label: string };

export type Palette = {
  actions: PaletteAction[];
  repeat?: boolean;
  ifElse?: boolean;
  conditions?: PaletteCondition[];
};

export type HintSet = { tier1: string[]; tier2: string[]; tier3: string[] };

export type Mission = {
  id: string;
  level: 1 | 2 | 3;
  order: number;
  title: string;
  subject: Subject;
  concept: Concept;
  story: string;
  goal: string;
  world: World;
  palette: Palette;
  optimalBlocks: number;
  hints: HintSet;
  /** Canonical solution: used for tests and leak-detection. NEVER sent to the client. */
  solution: Program;
};

/** Mission data that is safe to ship to the browser. */
export type ClientMission = Omit<Mission, "hints" | "solution">;

/* --------------------------------- Running --------------------------------- */

export type GridState = {
  kind: "grid";
  x: number;
  y: number;
  dir: Direction;
  cells: string[];
  collected: number;
};
export type NumberLineState = { kind: "numberline"; value: number };
export type SortState = {
  kind: "sort";
  itemIndex: number;
  placed: { item: number; bin: string; correct: boolean }[];
};
export type SequenceState = { kind: "sequence"; placed: { card: string; correct: boolean }[] };

export type WorldState = GridState | NumberLineState | SortState | SequenceState;

export type Frame = {
  blockId?: string;
  state: WorldState;
  /** Index of the layout/variant (grid) currently being run. */
  variant: number;
  note?: string;
  bad?: boolean;
};

export type FailureKind =
  | "bump"
  | "wrong-action"
  | "goal-not-reached"
  | "items-left"
  | "wrong-value"
  | "out-of-range"
  | "wrong-bin"
  | "not-placed"
  | "placed-twice"
  | "wrong-order"
  | "incomplete"
  | "too-long"
  | "invalid-program"
  | "empty";

export type RunFailure = {
  kind: FailureKind;
  blockId?: string;
  /** Child-friendly, positive message shown on screen. */
  message: string;
  /** Neutral diagnosis for Bibi's tier-3 hint. Never contains the full solution. */
  diagnosis: string;
  variant: number;
};

export type RunResult = {
  success: boolean;
  frames: Frame[];
  blocksUsed: number;
  failure?: RunFailure;
};

import {
  ENGINE_LIMITS,
  type Block,
  type Direction,
  type Frame,
  type GridState,
  type GridWorld,
  type Mission,
  type NumberLineWorld,
  type Palette,
  type Program,
  type RunFailure,
  type RunResult,
  type SequenceWorld,
  type SortWorld,
  type World,
  type WorldState,
} from "./types";

/* --------------------------------- Helpers --------------------------------- */

class Halt extends Error {
  constructor(public failure: Omit<RunFailure, "variant">) {
    super(failure.message);
  }
}

/** Total number of blocks in a program (containers count as one block each). */
export function countBlocks(program: Program): number {
  let n = 0;
  for (const b of program) {
    n += 1;
    if (b.kind === "repeat") n += countBlocks(b.body);
    if (b.kind === "if") n += countBlocks(b.then) + countBlocks(b.else);
  }
  return n;
}

export function programDepth(program: Program): number {
  let d = 0;
  for (const b of program) {
    if (b.kind === "repeat") d = Math.max(d, 1 + programDepth(b.body));
    else if (b.kind === "if") d = Math.max(d, 1 + programDepth(b.then), 1 + programDepth(b.else));
  }
  return d;
}

/**
 * Semantic validation: every block must be allowed by the mission palette.
 * Returns an error message (Indonesian, child-friendly) or null when valid.
 */
export function validateProgram(program: Program, palette: Palette): string | null {
  const actions = new Set(palette.actions.map((a) => a.action));
  const conds = new Set((palette.conditions ?? []).map((c) => c.id));
  if (countBlocks(program) > ENGINE_LIMITS.maxBlocks) {
    return `Programmu terlalu panjang. Maksimal ${ENGINE_LIMITS.maxBlocks} blok ya!`;
  }
  if (programDepth(program) > ENGINE_LIMITS.maxDepth) {
    return "Blok di dalam blok terlalu banyak tingkatnya.";
  }
  const walk = (blocks: Block[]): string | null => {
    for (const b of blocks) {
      if (b.kind === "action") {
        if (!actions.has(b.action)) return "Ada blok yang tidak dipakai di misi ini.";
      } else if (b.kind === "repeat") {
        if (!palette.repeat) return "Blok ulangi belum bisa dipakai di misi ini.";
        if (
          !Number.isInteger(b.times) ||
          b.times < ENGINE_LIMITS.minRepeat ||
          b.times > ENGINE_LIMITS.maxRepeat
        ) {
          return `Jumlah ulangi harus antara ${ENGINE_LIMITS.minRepeat} dan ${ENGINE_LIMITS.maxRepeat}.`;
        }
        const e = walk(b.body);
        if (e) return e;
      } else if (b.kind === "if") {
        if (!palette.ifElse) return "Blok jika belum bisa dipakai di misi ini.";
        if (!conds.has(b.cond)) return "Pilih dulu syarat untuk blok jika.";
        const e = walk(b.then) ?? walk(b.else);
        if (e) return e;
      } else {
        return "Ada blok yang tidak dikenal.";
      }
    }
    return null;
  };
  return walk(program);
}

type Runner = {
  act(action: string, blockId: string): void;
  test(cond: string): boolean;
};

function execute(program: Program, runner: Runner, counter: { steps: number; actions: number }) {
  const run = (blocks: Block[]) => {
    for (const b of blocks) {
      if (b.kind === "action") {
        counter.steps += 1;
        counter.actions += 1;
        if (counter.steps > ENGINE_LIMITS.maxSteps) {
          throw new Halt({
            kind: "too-long",
            blockId: b.id,
            message: "Programmu berjalan terlalu lama. Coba kurangi jumlah ulangi ya!",
            diagnosis: "Program menjalankan terlalu banyak langkah (kemungkinan ulangi terlalu besar).",
          });
        }
        runner.act(b.action, b.id);
      } else if (b.kind === "repeat") {
        for (let i = 0; i < b.times; i++) run(b.body);
      } else {
        counter.steps += 1;
        run(runner.test(b.cond) ? b.then : b.else);
      }
    }
  };
  run(program);
}

const clone = <T,>(v: T): T => JSON.parse(JSON.stringify(v)) as T;

/* ---------------------------------- Grid ----------------------------------- */

const DELTA: Record<Direction, [number, number]> = {
  N: [0, -1],
  E: [1, 0],
  S: [0, 1],
  W: [-1, 0],
};
const LEFT: Record<Direction, Direction> = { N: "W", W: "S", S: "E", E: "N" };
const RIGHT: Record<Direction, Direction> = { N: "E", E: "S", S: "W", W: "N" };

export function initialGridState(world: GridWorld, variant = 0): GridState {
  return {
    kind: "grid",
    x: world.start.x,
    y: world.start.y,
    dir: world.start.dir,
    cells: [...world.layouts[variant]],
    collected: 0,
  };
}

function cellAt(s: GridState, w: GridWorld, x: number, y: number): string | null {
  if (x < 0 || y < 0 || x >= w.width || y >= w.height) return null;
  return s.cells[y][x] ?? null;
}

function setCell(s: GridState, x: number, y: number, ch: string) {
  const row = s.cells[y];
  s.cells[y] = row.slice(0, x) + ch + row.slice(x + 1);
}

function runGridVariant(
  world: GridWorld,
  program: Program,
  variant: number,
  frames: Frame[],
): void {
  const s = initialGridState(world, variant);
  frames.push({ state: clone(s), variant });
  const counter = { steps: 0, actions: 0 };
  const label = (k: keyof NonNullable<GridWorld["legend"]>, fallback: string) =>
    world.legend?.[k] ?? fallback;

  const front = () => {
    const [dx, dy] = DELTA[s.dir];
    return { x: s.x + dx, y: s.y + dy };
  };
  const walkable = (c: string | null) => c !== null && c !== "#" && c !== "O";

  const runner: Runner = {
    act(action, blockId) {
      const step = counter.actions;
      const here = cellAt(s, world, s.x, s.y);
      switch (action) {
        case "forward": {
          const f = front();
          const c = cellAt(s, world, f.x, f.y);
          if (c === "O") {
            throw new Halt({
              kind: "bump",
              blockId,
              message: `Ada ${label("O", "🪨")} di depan! Coba cara lain untuk melewatinya.`,
              diagnosis: `Langkah ke-${step} memakai "maju" padahal di depan ada rintangan.`,
            });
          }
          if (!walkable(c)) {
            throw new Halt({
              kind: "bump",
              blockId,
              message: "Ups, jalannya buntu di depan! Coba cek arah dan langkahmu.",
              diagnosis: `Langkah ke-${step} ("maju") menabrak tembok atau keluar papan.`,
            });
          }
          s.x = f.x;
          s.y = f.y;
          break;
        }
        case "turnLeft":
          s.dir = LEFT[s.dir];
          break;
        case "turnRight":
          s.dir = RIGHT[s.dir];
          break;
        case "jump": {
          const f = front();
          const [dx, dy] = DELTA[s.dir];
          const landing = cellAt(s, world, f.x + dx, f.y + dy);
          if (cellAt(s, world, f.x, f.y) !== "O") {
            throw new Halt({
              kind: "wrong-action",
              blockId,
              message: "Di depan tidak ada yang perlu dilompati.",
              diagnosis: `Langkah ke-${step} memakai "lompat" padahal di depan tidak ada rintangan.`,
            });
          }
          if (!walkable(landing)) {
            throw new Halt({
              kind: "bump",
              blockId,
              message: "Tempat mendaratnya tidak aman.",
              diagnosis: `Langkah ke-${step} melompat ke tempat yang tidak bisa diinjak.`,
            });
          }
          s.x = f.x + dx;
          s.y = f.y + dy;
          break;
        }
        case "collect":
          if (here !== "I") {
            throw new Halt({
              kind: "wrong-action",
              blockId,
              message: `Di sini tidak ada ${label("I", "⭐")} untuk diambil.`,
              diagnosis: `Langkah ke-${step} memakai "ambil" di kotak yang kosong.`,
            });
          }
          setCell(s, s.x, s.y, ".");
          s.collected += 1;
          break;
        case "water":
          if (here === "P") setCell(s, s.x, s.y, "p");
          else if (here === "S") setCell(s, s.x, s.y, "s");
          else {
            throw new Halt({
              kind: "wrong-action",
              blockId,
              message:
                here === "p" || here === "s"
                  ? "Tanaman ini sudah disiram tadi. 💧"
                  : "Di sini tidak ada tanaman yang perlu disiram.",
              diagnosis: `Langkah ke-${step} memakai "siram" di kotak yang tidak perlu disiram.`,
            });
          }
          break;
        case "pick":
          if (here !== "R") {
            throw new Halt({
              kind: "wrong-action",
              blockId,
              message: "Di sini belum ada buah matang untuk dipetik.",
              diagnosis: `Langkah ke-${step} memakai "petik" di kotak tanpa buah matang.`,
            });
          }
          setCell(s, s.x, s.y, "r");
          break;
        default:
          throw new Halt({
            kind: "invalid-program",
            blockId,
            message: "Ada blok yang tidak dikenal.",
            diagnosis: "Blok tidak dikenal.",
          });
      }
      frames.push({ blockId, state: clone(s), variant });
    },
    test(cond) {
      const f = front();
      const ahead = cellAt(s, world, f.x, f.y);
      const here = cellAt(s, world, s.x, s.y);
      switch (cond) {
        case "rockAhead":
          return ahead === "O";
        case "pathAhead":
          return walkable(ahead);
        case "onRipe":
          return here === "R";
        case "onSeedling":
          return here === "S";
        case "onItem":
          return here === "I";
        case "onPot":
          return here === "P";
        default:
          return false;
      }
    },
  };

  execute(program, runner, counter);

  const all = s.cells.join("");
  const goalCell = cellAt(s, world, s.x, s.y);
  if (world.goal.collectAll && all.includes("I")) {
    const left = all.split("I").length - 1;
    throw new Halt({
      kind: "items-left",
      message: `Hebat, sudah jalan! Masih ada ${left} ${label("I", "⭐")} yang belum diambil.`,
      diagnosis: `Program selesai tetapi ${left} benda belum diambil.`,
    });
  }
  if (world.goal.waterAll && /[PS]/.test(all)) {
    const left = (all.match(/[PS]/g) ?? []).length;
    throw new Halt({
      kind: "items-left",
      message: `Bagus! Masih ada ${left} tanaman yang belum disiram.`,
      diagnosis: `Program selesai tetapi ${left} tanaman belum disiram.`,
    });
  }
  if (world.goal.pickAll && all.includes("R")) {
    const left = all.split("R").length - 1;
    throw new Halt({
      kind: "items-left",
      message: `Hampir! Masih ada ${left} buah matang yang belum dipetik.`,
      diagnosis: `Program selesai tetapi ${left} buah matang belum dipetik.`,
    });
  }
  if (world.goal.reach && goalCell !== "G") {
    let gx = 0;
    let gy = 0;
    s.cells.forEach((row, y) => {
      const x = row.indexOf("G");
      if (x >= 0) {
        gx = x;
        gy = y;
      }
    });
    const dist = Math.abs(gx - s.x) + Math.abs(gy - s.y);
    throw new Halt({
      kind: "goal-not-reached",
      message: `Hampir sampai! ${label("G", "🏁")} tinggal ${dist} kotak lagi.`,
      diagnosis: `Program selesai ${dist} kotak dari tujuan (setelah ${counter.actions} langkah).`,
    });
  }
}

/* ------------------------------- Number line ------------------------------- */

function parseNumberAction(action: string): number | null {
  const m = /^(add|sub):(\d+)$/.exec(action);
  if (!m) return null;
  const n = Number(m[2]);
  return m[1] === "add" ? n : -n;
}

function runNumberLine(world: NumberLineWorld, program: Program, frames: Frame[]) {
  const state = { kind: "numberline" as const, value: world.start };
  frames.push({ state: clone(state), variant: 0 });
  const counter = { steps: 0, actions: 0 };
  execute(
    program,
    {
      act(action, blockId) {
        const delta = parseNumberAction(action);
        if (delta === null) {
          throw new Halt({
            kind: "invalid-program",
            blockId,
            message: "Ada blok yang tidak dikenal.",
            diagnosis: "Blok tidak dikenal.",
          });
        }
        const next = state.value + delta;
        if (next < world.min || next > world.max) {
          frames.push({ blockId, state: { kind: "numberline", value: next }, variant: 0, bad: true });
          throw new Halt({
            kind: "out-of-range",
            blockId,
            message: `Wah, ${world.hero} melompat terlalu jauh sampai keluar garis bilangan!`,
            diagnosis: `Nilai menjadi ${next}, di luar garis ${world.min}–${world.max}. Target ${world.target}.`,
          });
        }
        state.value = next;
        frames.push({ blockId, state: clone(state), variant: 0 });
      },
      test: () => false,
    },
    counter,
  );
  if (state.value !== world.target) {
    const diff = world.target - state.value;
    throw new Halt({
      kind: "wrong-value",
      message: `${world.hero} berhenti di angka ${state.value}. Tujuannya angka ${world.target}, ayo coba lagi!`,
      diagnosis: `Nilai akhir ${state.value}, target ${world.target} (${diff > 0 ? "kurang" : "lebih"} ${Math.abs(diff)}).`,
    });
  }
}

/* ---------------------------------- Sort ----------------------------------- */

function runSort(world: SortWorld, program: Program, frames: Frame[]) {
  const state = { kind: "sort" as const, itemIndex: 0, placed: [] as { item: number; bin: string; correct: boolean }[] };
  frames.push({ state: clone(state), variant: 0 });
  const counter = { steps: 0, actions: 0 };
  const binLabel = (id: string) => world.bins.find((b) => b.id === id)?.label ?? id;

  world.items.forEach((item, i) => {
    state.itemIndex = i;
    let placedCount = 0;
    const name = `${item.emoji ?? ""} ${item.label}`.trim();
    execute(
      program,
      {
        act(action, blockId) {
          const m = /^bin:(.+)$/.exec(action);
          if (!m || !world.bins.some((b) => b.id === m[1])) {
            throw new Halt({
              kind: "invalid-program",
              blockId,
              message: "Ada blok yang tidak dikenal.",
              diagnosis: "Blok tidak dikenal.",
            });
          }
          if (placedCount > 0) {
            throw new Halt({
              kind: "placed-twice",
              blockId,
              message: `${name} tidak bisa masuk ke dua tempat sekaligus!`,
              diagnosis: `Untuk benda "${item.label}", program memindahkan benda lebih dari sekali.`,
            });
          }
          placedCount += 1;
          const correct = m[1] === item.answer;
          state.placed.push({ item: i, bin: m[1], correct });
          frames.push({ blockId, state: clone(state), variant: 0, bad: !correct });
          if (!correct) {
            const facts = Object.entries(item.props)
              .map(([k, v]) => `${k}=${v ? "ya" : "tidak"}`)
              .join(", ");
            throw new Halt({
              kind: "wrong-bin",
              blockId,
              message: `${name} masuk ke ${binLabel(m[1])}. Hmm, apakah itu tempat yang tepat? Coba cek aturanmu lagi.`,
              diagnosis: `Benda "${item.label}" (${facts}) masuk ke "${binLabel(m[1])}" padahal seharusnya ke tempat lain. Periksa syarat dan cabang JIKA/LAINNYA.`,
            });
          }
        },
        test(cond) {
          return Boolean(item.props[cond]);
        },
      },
      counter,
    );
    if (placedCount === 0) {
      throw new Halt({
        kind: "not-placed",
        message: `${name} belum dimasukkan ke tempat mana pun.`,
        diagnosis: `Untuk benda "${item.label}", tidak ada blok yang memindahkannya (cabang kosong?).`,
      });
    }
  });
}

/* -------------------------------- Sequence --------------------------------- */

function runSequence(world: SequenceWorld, program: Program, frames: Frame[]) {
  const state = { kind: "sequence" as const, placed: [] as { card: string; correct: boolean }[] };
  frames.push({ state: clone(state), variant: 0 });
  const counter = { steps: 0, actions: 0 };
  const cardLabel = (id: string) => world.cards.find((c) => c.id === id)?.label ?? id;

  execute(
    program,
    {
      act(action, blockId) {
        const m = /^card:(.+)$/.exec(action);
        if (!
